import{_ as e,o,c as d,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"Types","description":"","frontmatter":{"title":"Types","editLink":false},"headers":[],"relativePath":"reference/core/types.md","filePath":"reference/core/types.md"}'),n={name:"reference/core/types.md"};function s(a,t,l,c,i,u){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h1><p>Enums and types declared in <code>FlowTypes.h</code>.</p><h2 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h2><h3 id="efpstoptype" tabindex="-1">EFPStopType <a class="header-anchor" href="#efpstoptype" aria-label="Permalink to &quot;EFPStopType&quot;">​</a></h3><p>FlowPilot Stop Type</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>Cancel Execution</strong><br><sub><code>CancelExecution</code></sub></td><td>Cancel Execution will call Exit with Failure state on Running Tasks</td></tr><tr><td><strong>Stop Now</strong><br><sub><code>StopNow</code></sub></td><td>Stop Now will just stop execution. Exit won&#39;t be called.</td></tr></tbody></table><h3 id="efptaskresult" tabindex="-1">EFPTaskResult <a class="header-anchor" href="#efptaskresult" aria-label="Permalink to &quot;EFPTaskResult&quot;">​</a></h3><p>Task Execution Result</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>None</strong><br><sub><code>None</code></sub></td><td>Not started yet</td></tr><tr><td><strong>In Progress</strong><br><sub><code>InProgress</code></sub></td><td>In progress and Ticking</td></tr><tr><td><strong>Succeeded</strong><br><sub><code>Succeeded</code></sub></td><td>Complete with Success Result</td></tr><tr><td><strong>Failed</strong><br><sub><code>Failed</code></sub></td><td>Complete with Fail Result</td></tr><tr><td><strong>Error</strong><br><sub><code>Error</code></sub></td><td>Not Complete. Return Error</td></tr></tbody></table><h3 id="eflowstate" tabindex="-1">EFlowState <a class="header-anchor" href="#eflowstate" aria-label="Permalink to &quot;EFlowState&quot;">​</a></h3><p>Flow State</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>None</strong><br><sub><code>None</code></sub></td><td>Not started yet</td></tr><tr><td><strong>In Progress</strong><br><sub><code>InProgress</code></sub></td><td>FlowPilot Running</td></tr><tr><td><strong>Paused</strong><br><sub><code>Paused</code></sub></td><td>FlowPilot has started but is paused</td></tr><tr><td><strong>Succeeded</strong><br><sub><code>Succeeded</code></sub></td><td>FlowPilot Done with Success</td></tr><tr><td><strong>Failed</strong><br><sub><code>Failed</code></sub></td><td>FlowPilot Done with fail</td></tr><tr><td><strong>Error</strong><br><sub><code>Error</code></sub></td><td>FlowPilot not Done, with Error</td></tr></tbody></table><h3 id="efpactorscope" tabindex="-1">EFPActorScope <a class="header-anchor" href="#efpactorscope" aria-label="Permalink to &quot;EFPActorScope&quot;">​</a></h3><p>Actor Scope</p><ul><li>Helps determine the search scope when referencing an actor with FFlowActorReference</li></ul><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>Self</strong><br><sub><code>Self</code></sub></td><td>Actor or Component is in Own Actor</td></tr><tr><td><strong>In Level</strong><br><sub><code>InLevel</code></sub></td><td>Actor that live in the world</td></tr><tr><td><strong>Runtime</strong><br><sub><code>Runtime</code></sub></td><td>Actors spawned at Runtime</td></tr></tbody></table><h3 id="efpspawnlifetime" tabindex="-1">EFPSpawnLifetime <a class="header-anchor" href="#efpspawnlifetime" aria-label="Permalink to &quot;EFPSpawnLifetime&quot;">​</a></h3><p>Spawn Lifetime Enum</p><ul><li>Helps Setup automatic Destroy when lifetime is bound to a FlowPilot Execution</li></ul><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>Flow Pilot</strong><br><sub><code>FlowPilot</code></sub></td><td>Spawned actor will live during FlowPilot Execution, will despawn automatically when Flow Ends.</td></tr><tr><td><strong>Persistent</strong><br><sub><code>Persistent</code></sub></td><td>TODO (MA): Add a Checkpoint lifetime? or internal scope, example, when we add another FlowAsset, or a Parallel, sequence or selector. Spawned actors will stay on the level event when Flow Stops.</td></tr></tbody></table><h3 id="efpexecutionmode" tabindex="-1">EFPExecutionMode <a class="header-anchor" href="#efpexecutionmode" aria-label="Permalink to &quot;EFPExecutionMode&quot;">​</a></h3><p>Execution Mode</p><ul><li>Dictates how we should run a FlowPilot asset</li></ul><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>Run Once</strong><br><sub><code>RunOnce</code></sub></td><td>Executes Flow Once.</td></tr><tr><td><strong>Run Until Succeed</strong><br><sub><code>RunUntilSucceed</code></sub></td><td>Executes until Succeeds Once</td></tr><tr><td><strong>Run Until Fail</strong><br><sub><code>RunUntilFail</code></sub></td><td>Executes until Fails Once</td></tr><tr><td><strong>Run While Succeed</strong><br><sub><code>RunWhileSucceed</code></sub></td><td>Executes in Loop while Succeeds</td></tr><tr><td><strong>Run While Fail</strong><br><sub><code>RunWhileFail</code></sub></td><td>Executes in Loop while Fails</td></tr><tr><td><strong>Run Non Stop</strong><br><sub><code>RunNonStop</code></sub></td><td>Run non stop.</td></tr></tbody></table><h2 id="fflowcontext" tabindex="-1">FFlowContext <a class="header-anchor" href="#fflowcontext" aria-label="Permalink to &quot;FFlowContext&quot;">​</a></h2><p>Flow Context</p><ul><li>Contains information passed to each Task that has information about their owner, and runners.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>World</code></td><td><code>UWorld</code></td><td></td></tr><tr><td><code>OwnerActor</code></td><td><code>AActor</code></td><td></td></tr><tr><td><code>OwnerComponent</code></td><td><a href="./../components/flowpilot-component"><code>UFlowPilotComponent</code></a></td><td></td></tr></tbody></table>',28)])])}const p=e(n,[["render",s]]);export{h as __pageData,p as default};
